        return None

    if not cwd.startswith('/') or cwd == '':
        return None

    # Normalize cwd to not have trailing slash (except for root)
    if cwd != '/' and cwd.endswith('/'):
        return None

    # Start with cwd if path is relative, otherwise start with empty
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

