        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            # Move to parent
            if current == '':
                current = '/'
            elif current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            current = '/' + component
        else:
            current = current + '/' + component

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            # Get the target
            target = links[current]

            # Determine the base path for relative targets
            if target.startswith('/'):
                # Absolute target
                current = ''
                target_components = target.split('/')
            else:
                # Relative target - relative to the directory containing the link
                if current == '/':
                    base = '/'
                else:
                    base = current.rsplit('/', 1)[0]
                    if base == '':
                        base = '/'

                current = base
                target_components = target.split('/')

            # Replace remaining components with target components
            components = target_components + components[i+1:]
            i = 0
            continue

        i += 1

    # Return the result
    if current == '':
        return '/'
    return current

